# Re-run the algorithm with correct input
def transform(input_grid, marker_val, fill_val=2):
    h, w = len(input_grid), len(input_grid[0])

    # Find all marker positions
    all_markers = []
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == marker_val:
                all_markers.append((r, c))

    if not all_markers:
        return [row[:] for row in input_grid]

    # Find extent
    min_r = min(r for r, c in all_markers)
    max_r = max(r for r, c in all_markers)
    min_c = min(c for r, c in all_markers)
    max_c = max(c for r, c in all_markers)

    # Create output grid as copy of input
    output = [row[:] for row in input_grid]

    # Step 1: For border columns (min_c and max_c), fill fill_val except at markers
    for bc in [min_c, max_c]:
        for r in range(min_r, max_r + 1):
            if input_grid[r][bc] != marker_val:
                output[r][bc] = fill_val

    # Step 2: For top boundary row (min_r), fill all between min_c and max_c, skip markers
    for c in range(w):
        if input_grid[min_r][c] != marker_val and min_c <= c <= max_c:
            output[min_r][c] = fill_val

    # Step 3: For bottom boundary row (max_r), fill between consecutive markers
    zeros_in_bottom = sorted([c for c in range(w) if input_grid[max_r][c] == marker_val])
    for i in range(len(zeros_in_bottom) - 1):
        for c in range(zeros_in_bottom[i] + 1, zeros_in_bottom[i + 1]):
            output[max_r][c] = fill_val

    # Step 4: For middle rows (min_r < r < max_r), handle based on markers
    for r in range(min_r + 1, max_r):
        markers_in_row = sorted([c for c in range(w) if input_grid[r][c] == marker_val])

        if not markers_in_row:
            # No markers: fill border columns (min_c and max_c)
            if min_c < w and max_c < w:
                output[r][min_c] = fill_val
                output[r][max_c] = fill_val
        elif len(markers_in_row) == 1:
            # One marker: fill borders except at marker position
            if markers_in_row[0] == min_c and max_c < w:
                output[r][max_c] = fill_val
            elif markers_in_row[0] == max_c and min_c < w:
                output[r][min_c] = fill_val
            else:
                output[r][min_c] = fill_val
                output[r][max_c] = fill_val
        else:
            # Multiple markers: fill intervals between consecutive markers
            for i in range(len(markers_in_row) - 1):
                for c in range(markers_in_row[i] + 1, markers_in_row[i + 1]):
                    output[r][c] = fill_val

    return output

